CREATE OR REPLACE VIEW CORE.FCT_METER_READING (
    READING_ID COMMENT 'Identifier ''reading id''. Origin: FM Business Layer.MeterReading.ReadingID',
    DATE_KEY COMMENT 'Foreign key to Date (MeterReading_to_Date)',
    METER_ID COMMENT 'Foreign key to Meter (MeterReading_to_Meter)',
    TARIFF_ID COMMENT 'Foreign key to Tariff (MeterReading_to_Tariff)',
    IS_INTERVAL_READ COMMENT 'Attribute ''is interval read''. Origin: FM Business Layer.MeterReading.IsIntervalRead',
    READING_DATE COMMENT 'Attribute ''reading date''. Origin: FM Business Layer.MeterReading.ReadingDate',
    CO2_ESTIMATE_KG COMMENT 'Estimated CO2 emissions at 0.233 kg/kWh (US EPA average grid emission factor)',
    CONSUMPTION_KWH COMMENT 'Measure ''consumption kwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ConsumptionKWh',
    CONSUMPTION_MWH COMMENT 'Measure ''consumption mwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ConsumptionMWh',
    OFF_PEAK_KWH COMMENT 'Measure ''off peak kwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.OffPeakKWh',
    PEAK_DEMAND_KW COMMENT 'Measure ''peak demand kw''; default aggregation MAX (semi-additive). Origin: FM Business Layer.MeterReading.PeakDemandKW',
    REACTIVE_KVARH COMMENT 'Measure ''reactive kvarh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ReactiveKVARh'
)
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Billing_Package', GOV.RETENTION = '7 years (FERC)')
  COMMENT = 'Fact at MeterReading grain. Source: CC_AND_B_PROD.METER_READING. Origin: FM Business Layer.MeterReading'
AS
SELECT
    src.READING_ID                                AS READING_ID,
    src.DATE_KEY                                  AS DATE_KEY,
    src.METER_ID                                  AS METER_ID,
    src.TARIFF_ID                                 AS TARIFF_ID,
    src.IS_INTERVAL_READ                          AS IS_INTERVAL_READ,
    src.READING_DATE                              AS READING_DATE,
    src.CONSUMPTION_KWH * ref_1.FACTOR_VALUE      AS CO2_ESTIMATE_KG,
    src.CONSUMPTION_KWH                           AS CONSUMPTION_KWH,
    src.CONSUMPTION_KWH / 1000                    AS CONSUMPTION_MWH,
    src.OFF_PEAK_KWH                              AS OFF_PEAK_KWH,
    src.PEAK_DEMAND_KW                            AS PEAK_DEMAND_KW,
    src.REACTIVE_KVARH                            AS REACTIVE_KVARH
FROM RAW_CCB.METER_READING src
-- F12: externalized constant
LEFT JOIN REF.REF_EMISSION_FACTOR ref_1
    ON ref_1.FACTOR_CODE = 'METER_READING_CO2_ESTIMATE_KG' AND src.READING_DATE >= ref_1.EFFECTIVE_FROM AND src.READING_DATE < COALESCE(ref_1.EFFECTIVE_TO, '9999-12-31'::DATE);

